const shots = document.querySelector('.shots')
shots.addEventListener('dio:index', (e) => {
  document.querySelector('.count').value = String(e.detail.index + 1)
})
document.querySelector('.next').onclick = () => {
  const gallery = app.effects.get(shots, 'gallery')
  gallery?.set({ index: Math.round(gallery.params.index) + 1 })
}

const deck = document.querySelector('.deck')
const names = [...deck.querySelectorAll('img')].map((img) => img.alt)
deck.addEventListener('dio:index', (e) => {
  document.querySelector('.count').textContent = names[e.detail.index]
})

const work = document.querySelector('.work')
const names = [...work.querySelectorAll('img')].map((img) => img.alt.split(':')[0])
work.addEventListener('dio:index', (e) => {
  document.querySelector('.title').textContent = names[e.detail.index]
})

const board = document.querySelector('.board')
document.querySelector('.shuffle').addEventListener('click', () => {
  const prints = app.effects.get(board, 'polaroids')
  prints?.set({ seed: prints.params.seed + 1 })
})

const talk = document.querySelector('.talk')
const play = document.querySelector('.play')
play.addEventListener('click', () => (talk.paused ? talk.play() : talk.pause()))
talk.addEventListener('play', () => play.setAttribute('aria-pressed', 'true'))
talk.addEventListener('pause', () => play.setAttribute('aria-pressed', 'false'))
